firmware:
#include <DHT.h>

const int DHT_PIN = 15;
const int LDR_PIN = 34;
DHT dht(DHT_PIN, DHT22);

void setup() {
  Serial.begin(115200);
  dht.begin();
}

void loop() {
  delay(2000);
  float t = dht.readTemperature();
  if (isnan(t)) {
    return;
  }
  int light = analogRead(LDR_PIN);
  Serial.print("T=");
  Serial.print(t);
  Serial.print(" L=");
  Serial.println(light);
}
